// uk — Українська (ucraniano).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// TRATAMENTO: **ти**, e não *ви*. É o que o CLAUDE.md manda, e é o registro dos aplicativos de
// conversa em ucraniano. Minúsculo, como em toda interface.
//
// ONDE O UCRANIANO ESCONDE O GÊNERO — o mesmo lugar do polonês, que veio antes:
//
//   1. no PASSADO: забув (homem) / забула (mulher) — "esqueceu a senha?";
//   2. no CONDICIONAL, que é o passado com "б": хотів би / хотіла б;
//   3. em ADJETIVO E PARTICÍPIO curto depois de "ser": впевнений / впевнена, вимкнений / вимкнена.
//
// A saída é a mesma: o PRESENTE e o FUTURO PERFECTIVO são neutros (маєш, можеш, втратиш), e a frase
// é reescrita para passar por eles. "Не пам’ятаєш пароль?" em vez de "забув"; "Мікрофон вимкнено"
// (forma impessoal em -но, que não tem sexo) em vez de "ти вимкнений"; "Точно видалити…?" em vez de
// "ти впевнений". As formas impessoais em -но/-то (створено, надіслано, змінено) são a ferramenta
// principal deste arquivo: elas dizem que aconteceu sem dizer quem.
//
// Os NOMES DE CARGO (Адміністратор, Власник, Учасник) ficam no masculino genérico, como em toda
// interface ucraniana — são rótulos de papel.
//
// ---------------------------------------------------------------------------------------------------
// PLURAL: três formas (1 повідомлення, 2–4 повідомлення, 5+ повідомлень — e 11–14 vão para a
// terceira). O t() não escolhe forma, então vale a saída do russo: rótulo e número, "Повідомлень: {n}".
//
// APÓSTROFO: o ucraniano o usa DENTRO da palavra (пам’ять, м’який, з’єднання). Aqui ele vai como ’
// (U+2019), que é o que as interfaces ucranianas usam — e que não briga com as aspas simples do
// arquivo. O ' reto exigiria escapar, e escapar já sumiu com pares inteiros calado (ver a armadilha
// do hauçá em web/test/traducao.test.ts).
//
// ALGARISMOS, medidos e não supostos: `Intl.NumberFormat('uk').format(1234567)` devolve `1 234 567`,
// e o número grande sai "40 млн". São os latinos; os números deste arquivo vão com 0-9.
//
// ASPAS: as ucranianas são «assim».
//
// VOCABULÁRIO, decidido uma vez: comunidade = спільнота, canal = канал, sala de voz = голосова
// кімната, chamada = дзвінок, conversa = розмова, mensagem = повідомлення, senha = пароль, lixeira =
// кошик, tópico = гілка, conta = обліковий запис, dono = власник, cargo = роль, convite =
// запрошення, pedido de amizade = запит у друзі, amigos = друзі, perfil = профіль, transmissão =
// трансляція, recado = запис, soundboard = звукова панель, vila = село, guarda-roupa = гардероб,
// denúncia = скарга, tela = екран.
//
// SELO E INSÍGNIA SEPARADOS: selo = печатка (o da comunidade), insígnia = значок (o da pessoa).

