  'Desconectar': 'Відключити',
  'Descrição': 'Опис',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'Коли вимкнено, трансляція людей у кімнаті з’являється як запрошення й починає завантажуватися лише після натискання «Дивитися». Це економить інтернет і процесор — особливо в повній кімнаті.',
  'Desligar câmera': 'Вимкнути камеру',
  'Deste servidor': 'З цієї спільноти',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.': 'Вкажи пошту свого облікового запису, і ми надішлемо посилання, щоб вибрати новий.',
  'Digite sua senha para confirmar': 'Введи пароль для підтвердження',
  'Disponível': 'Онлайн',
  'Do laranja ao vermelho, como carvão aceso.': 'Від помаранчевого до червоного, як розжарене вугілля.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Два емодзі з однаковою назвою: кожному потрібна своя.',
