  'Dono da comunidade': 'Власник спільноти',
  'Dourado com brilho que passa devagar.': 'Золотий із повільним відблиском.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'Під час дзвінка ця кнопка відтворює ці звуки для всіх у кімнаті. Встанови готові набори або завантаж свої; улюблені стоять на початку панелі.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'Це перше, що людина бачить, коли заходить у спільноту, лише один раз. Без цього вона потрапляє одразу до списку каналів.',
  'É assim que os outros veem você na lista e nas conversas.': 'Так тебе бачать інші у списку й у розмовах.',
