  'Estrelas necessárias': 'Потрібно зірок',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Коли повідомлення набирає досить зірок ⭐, Syden публікує його в каналі вибраного. Зірка від автора повідомлення не рахується, а видалення повідомлення видаляє і вибране.',
