  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden оголошує приз у каналі, а хто хоче взяти участь, ставить 🎉. У призначений час він розігрує приз серед тих, хто поставив реакцію, і публікує підсумки.',
