  'Dia': 'День',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Сьогодні день народження у {pessoa}! 🎉 З днем народження!',
  'Mês': 'Місяць',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'У день народження того, хто вказав дату, Syden публікує привітання у вибраному каналі. Використовуй {pessoa} замість імені.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Лише день і місяць, ніколи рік. Спільноти, що оголошують дні народження, вітають цього дня. Це необовʼязково, і видалити можна будь-коли.',
