  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Скільки кожен чекає між повідомленнями в каналі.',
  'Regras': 'Правила',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Правила, які Syden застосовує сам, до того як повідомлення з’явиться. На адміністраторів вони не діють. Заблоковане повідомлення повертається авторові з причиною, і більше його ніхто не бачить.',
  'Salvo.': 'Збережено.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'По одному в рядку. Враховується слово цілком, без різниці в наголосах і регістрі: заборона слова не блокує довшого слова, яке лише його містить.',
