  'Feliz aniversário, {nome}!': 'З днем народження, {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'Нехай цей рік буде повний добрих розмов, добрих ігор і доброї компанії.',
