  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'Твій мікрофон заблоковано: тебе ніхто не чує.',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'Блокує Windows. Відкрий Параметри Windows → Конфіденційність і захист → Мікрофон і дозволь доступ браузеру.',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'Натисни на значок ліворуч від адреси сайту, увімкни Мікрофон, і Syden сам його ввімкне.',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.': 'Твій мікрофон не передає звук: тебе ніхто не чує. Натисни, щоб вибрати інший.',
