  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.':
    'У твоїй трансляції немає звуку. Браузер надсилає звук, лише якщо позначити «поділитися аудіо» у віконці вибору екрана.',
  'Sua voz': 'Твій голос',
  'Suba músicas que você já tem. Um arquivo': 'Завантажуй пісні, які вже маєш. Файл',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.':
    'Завантажуй лише своє або те, що маєш право використовувати. Мати файл — не те саме, що мати право відтворювати його іншим.',
  'Sugestões de melhoria': 'Пропозиції щодо покращень',
  'Supressão de ruído': 'Шумозаглушення',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.':
    'Також можна перетягувати край кожної панелі на екрані. Подвійний клік по краю повертає типову ширину.',
  'Também dá para colar o endereço de um GIF ou de uma imagem. O Syden baixa uma cópia e guarda: se o endereço sair do ar depois, a capa continua.':
    'Також можна вставити адресу GIF чи зображення. Syden завантажує копію й зберігає її: якщо адреса згодом перестане працювати, обкладинка лишиться.',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.':
    'Теж безкоштовні й теж змінюються будь-коли. Вони в налаштуваннях спільноти, бо діють для всієї спільноти, а не лише для тебе.',
