  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.':
    'Відтворює звук, коли хтось заходить у твою кімнату чи виходить, коли хтось починає демонстрацію екрана і коли ти вимикаєш мікрофон чи звук.',
  'Tocando…': 'Відтворення…',
  'Toda letra com a mesma largura.': 'Усі літери однакової ширини.',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'Усі кольори повільно обертаються. Найпомітніший з усіх.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.':
    'Усі в цій спільноті можуть використовувати ці емодзі, написавши {exemplo} або через кнопку емодзі в чаті. Без підписки: усе відкрито.',
  'Tom mais alto e mais claro.': 'Вищий і світліший тон.',
