  'Outros jogos': 'Інші ігри',
  'Stop': 'Стоп',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Випадає літера, і кожен пише на неї слово в кожній категорії. Хто першим заповнить усе, тисне СТОП, а компанія вирішує, що зарахувати.',
  'Sudoku': 'Судоку',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Усі отримують однакове судоку, а кімната бачить, хто ближче до фінішу.',
  'Cinco em linha': 'Гомоку',
