  'Mancala': 'Манкала',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Гра в посів: візьми насіння з лунки й розклади по одному в наступні лунки. Перемагає той, у кого більше в коморі. Кімната дивиться.',
