  'Lobisomem': 'Перевертень',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Уночі разом з іншими перевертнями обери, на кого напасти. Удень не дай нікому себе запідозрити.',
  'Vidente': 'Оракул',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Уночі дізнайся, чи хтось перевертень. Розкажи вдень, якщо ризик того вартий.',
  'Anjo': 'Ангел',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Уночі обери, кого захистити. Напад перевертнів на цю людину не спрацює.',
  'Da vila': 'Із села',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Уночі спи. Удень виріши, хто перевертні, і голосуй, щоб вивести їх із гри.',
