  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'День {n}. Обговоріть і проголосуйте за того, кого вважаєте перевертнем.',
  'A vila tirou {nome} do jogo.': 'Село вивело з гри: {nome}.',
