  'O arquivo': 'Файл',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}): прибрано з Syden, бо {quem} заявляє про свої права на це. Якщо в тебе був дозвіл на публікацію, відповідай тут і розкажи: твою відповідь врахують. Поки це не з\'ясується, матеріал лишається прибраним. Як це працює, пояснено в розділі 4 умов: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}»: прибрано.',
