  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Тепер Syden питає вік у всіх, щоб захистити тих, кому менше 18 років (закон ECA Digital). Твою дату ніхто не бачить: використовується лише вікова група.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Кому повідомлено і номер звернення (напр.: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'З міркувань безпеки попередній перегляд трансляцій закритий для неповнолітніх.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'З міркувань безпеки неповнолітні листуються особисто лише з друзями.',
  'Qual é a sua data de nascimento?': 'Яка твоя дата народження?',
  'Quem muda estas regras é o seu responsável.': 'Ці правила змінюють твої батьки.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'Ті, кому 13–15 років, користуються Syden з обліковим записом, прив’язаним до облікового запису батьків або опікуна. Так вимагає закон (ECA Digital), і це для твоєї безпеки.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'Ті, кому менше 18 років, користуються Syden з додатковим захистом, а в 13–15 років — з обліковим записом, прив’язаним до батьків (закон ECA Digital).',
  'Recorrer da decisão': 'Оскаржити рішення',
  'Recurso em {quando}:': 'Оскарження {quando}:',
  'Registrar a comunicação': 'Зареєструвати повідомлення владі',
  'Só contas de menores de idade se ligam a um responsável.': 'До батьків прив’язуються лише облікові записи неповнолітніх.',
  'Só um adulto pode ser o responsável por outra conta.': 'Відповідати за інший обліковий запис може лише дорослий.',
  'Sua conta tem uma pendência. Abra o Syden de novo para ver o que fazer.': 'Із твоїм обліковим записом треба дещо вирішити. Відкрий Syden знову, щоб дізнатися, що робити.',
  'Suspender por idade': 'Призупинити через вік',
  'suspensa por idade': 'призупинений через вік',
  'Também dá para escrever para contato@syden.chat.': 'Також можна написати на contato@syden.chat.',
