  'Escolha onde a muralha começa.': 'Обери, де починається мур.',
  'Agora a outra ponta da muralha.': 'Тепер інший кінець муру.',
  'Vitória!': 'Перемога!',
  'Derrota': 'Поразка',
  'Você desistiu.': 'Партію здано.',
  'O tempo acabou: ganhou quem tinha mais.': 'Час вийшов: переміг той, у кого було більше.',
  'A sua Maravilha ficou de pé por 2 minutos.': 'Твоє Диво простояло 2 хвилини.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'Диво комп’ютера простояло 2 хвилини.',
