  'Este jogo não se joga na sala.': 'У цю гру не грають у кімнаті.',
  'Ponha os seus navios no mar.': 'Розстав свої кораблі в морі.',
  'Esperando {nome} pôr os navios…': 'Чекаємо, поки {nome} розставить кораблі…',
  'Os dois estão pondo os navios…': 'Обидві сторони розставляють кораблі…',
  'Navio de {n} casas': '{n}-палубний корабель',
  'Seus navios': 'Твої кораблі',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Обери корабель і торкнися моря. Перетягни, щоб пересунути.',
  'Sortear a frota': 'Випадковий флот',
  'Sua frota já está pronta.': 'Твій флот уже готовий.',
  'Ponha todos os navios antes.': 'Спершу розстав усі кораблі.',
  'Escolha um navio.': 'Обери корабель.',
  'O navio não cabe aí.': 'Корабель сюди не вміщається.',
  'Os navios não podem encostar um no outro.': 'Кораблі не можуть торкатися один одного.',
  'Minigolfe 3D': 'Міні-гольф 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Вісім лунок у 3D, з гірками, замком і вітряком, усі грають одну й ту саму одночасно. Тягни, щоб прицілитися й задати силу, і відпусти. Перемагає той, у кого в сумі найменше ударів.',
  'Ver o buraco de cima': 'Подивитися на лунку згори',
  'Fora da pista! Mais uma tacada.': 'За межами доріжки! Плюс один удар.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Тягни вбік, щоб цілитися, і вниз для сили, і відпусти. На клавіатурі: стрілки цілять, а затиснутий пробіл дає силу.',
  'Futebol dos coelhos': 'Кролячий футбол',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Міні-футбол, вигляд згори. Торкнися мʼяча, щоб вести його, затисни пробіл, щоб ударити сильніше, і пасуй на X. У кімнаті команди доповнюються ботами.',
  'Quantos por time?': 'Скільки в команді?',
  'Seu time venceu!': 'Твоя команда перемогла!',
  'Seu time perdeu.': 'Твоя команда програла.',
  'Passe': 'Пас',
  'Chutar': 'Удар',
  'Chutar (segure para mais força)': 'Удар (затисни для більшої сили)',
  'Gol!': 'Гол!',
  'Gol contra': 'Автогол',
  'Partida inválida.': 'Недійсна партія.',
  'Ninguém para jogar.': 'Нема з ким грати.',
  'Caça às pragas da horta': 'Полювання на шкідників городу',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Ворони й коники нападають на город. Цілься і клацай, щоб влучити, поки вони не втекли: набоїв обмаль, і кожна хвиля швидша за попередню. Перемагає той, хто набере найбільше очок.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Цілься і клацай по шкідниках, поки вони не втекли. Кожен постріл коштує одну морквину.',
  'Munição: {n}': 'Набої: {n}',
  'Pontos: {n}': 'Очки: {n}',
  'Nesta onda': 'У цій хвилі',
  'Acabou a munição desta onda.': 'Набої на цю хвилю скінчилися.',
  'Tiro inválido.': 'Недійсний постріл.',
  'Tabuleiro da turma': 'Настілка компанії',
