  'Subir a pilha': 'Підняти стопку',
  'Setas para mover, Espaço para trocar, X para subir a pilha.': 'Стрілки — рух, пробіл — обмін, X — підняти стопку.',
  'A horta está salva!': 'Город урятовано!',
  'A horta caiu.': 'Город упав.',
  'Campanha': 'Кампанія',
  'Sem vidas.': 'Життів немає.',
