  'Pular': 'Стрибок',
  'Bater': 'Удар',
  'Neste buraco': 'На цій лунці',
  'Total': 'Усього',
  'Tacadas: {n}': 'Удари: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Відтягни мʼяч назад і відпусти. На клавіатурі: стрілки цілять, а затиснутий пробіл дає силу.',
  'Na água! Mais uma tacada.': 'У воду! Плюс один удар.',
  'No buraco!': 'У лунці!',
  'Acabaram as tacadas.': 'Удари закінчилися.',
  'Para a esquerda': 'Ліворуч',
  'Para a direita': 'Праворуч',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Стрілки — біг, пробіл — стрибок (затисни, щоб стрибнути вище).',
  'Nenhum amigo jogou esta fase ainda.': 'Цей рівень ще не проходив ніхто з друзів.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Дощ на городі: усі отримують {n} морквин.',
  '{nome} achou {n} cenouras escondidas.': '{nome} знаходить {n} схованих морквин.',
  '{nome} trocou de lugar com {outro}.': '{nome} міняється місцями з {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Забракло людей: партія скінчилася раніше, без кубків.',
  'Saiu antes do fim': 'Вихід до кінця гри',
  'Jogar o dado': 'Кинути кубик',
  '{nome} comprou a cenoura dourada!': '{nome} купує золоту моркву!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Купити золоту моркву за {preco} морквин?',
  'Comprar': 'Купити',
  '{nome} chegou à cenoura dourada.': '{nome} дістається до золотої моркви.',
  'Quantas rodadas?': 'Скільки раундів?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Кролики боронять город від лисиць, ворон і борсука. Ідіть разом, бийте комбо й бережіть одне одного: від 1 до 4 людей.',
  'Pulo do coelho': 'Кролячий стрибок',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Перегони платформами: біжи, стрибай і не падай. Соло — на час і з привидами друзів; з компанією — наживо, на одному рівні або на всіх трьох.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Міняй місцями два сусідні овочі, щоб зібрати три однакові або більше. Стопка росте без упину: не дай їй дійти до верху. З компанією ланцюжки й комбо надсилають ящики іншим.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Шість лунок міні-гольфу, усі грають ту саму одночасно. Відтягни мʼяч назад і відпусти, щоб ударити. Перемагає той, у кого загалом найменше ударів.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Кожен у свій хід кидає кубик і йде городом. Збирай моркву, щоб купити золоту моркву, а після кожного раунду компанія грає в мінігру. Перемагає той, у кого найбільше золотих морквин.',
  'Os pódios e as conquistas da turma': 'П’єдестали й досягнення компанії',
  'Visitar o quarto': 'Зайти в кімнату',
