  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Ходи столицями Бразилії, купуй міста й бери оренду з тих, хто на них зупиниться. Зібравши весь регіон, можна будувати будинки. Обмінюйся, змагайся на аукціонах і не залишися без грошей.',
