  'Damas': 'Шашки',
  'Batalha naval': 'Морський бій',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Класичне доміно на 2–4 гравців (учотирьох — парами). Приставляй кістки до кінців ланцюжка, і хто першим викладе всі, забирає очки з рук інших.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Труко паулішта, з відкритою картою й козирями, удвох або парами вчотирьох. Оголошуй труко, підвищуй до шести, дев\'яти й дванадцяти або тікай. Перемагає той, хто набере 12 очок.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Бразильські шашки: бити обов\'язково, уперед і назад, а дамка ходить усією діагоналлю. Кімната дивиться.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Кожен ховає свій флот і стріляє по морю іншого. Влучив — стріляєш ще раз. Перемагає той, хто першим потопить увесь флот. Кімната дивиться.',
