  Bispo: 'Слон',
  'Cozinha da toca': 'Кухня в норі',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Бери продукти з ящиків, наріж на дошці, приготуй на плиті й у духовці, не спаливши, поклади на тарілку й віддай у віконце. Усі отримують однакові замовлення: перемагає той, хто за 3 хвилини віддасть найбільше тарілок.',
  'Pegar ou largar': 'Взяти або покласти',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Цій грі потрібна 3D-графіка, яка не відкрилася на цьому пристрої.',
