  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Обмежені журнали Docker, SSH, logind і ядра за три останні завантаження. Можуть містити IP-адреси.",
  "Atualizar diagnóstico": "Оновити діагностику",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Знімка ще немає. Його буде зібрано під час наступного відкриття сейфа.",
