  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Ті самі цифри, що в панелі провайдера. Разом із диском, який сервер сам не вимірює.",
  "Ações no servidor": "Дії із сервером",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Історія в Hetzner: увімкнення, вимкнення й перезавантаження з панелі або через API. Збій без дії тут не був спричинений цими шляхами.",
