  'Seu palpite está salvo. Dá para mudar até fechar.': "Твій прогноз збережено. Його можна змінити до закриття.",
  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Фон камери",
  'Desfocado': "Розмити",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Розмиває, прибирає або замінює те, що видно в тебе за спиною. Зображення з камери для цього не залишає твій комп'ютер.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Рідна",
  'Resolução': "Роздільність",
  'Quadros por segundo': "Кадри за секунду",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "На випадок, коли автоматичний вибір помиляється: роздільність і кадри лишаються такими, як ти обереш, від початку до кінця трансляції.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Ефекти для голосу й камери, які працюють на твоєму комп'ютері, нічого не надсилаючи на сервер.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Підземелля нори",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Пройдіть разом нору короля-гриба: кімнати, повні звірят, скриня з морквою, що летить туди й назад, кнопки, яким потрібні двоє одночасно, і замкнені двері. Від 1 до 4 людей.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ринг біля нори",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Бокс на реакцію проти трьох суперників-комп’ютерів. Читай попередження кожного удару, ухиляйся або блокуй і бий у пролом. Удар, коли рукавиця блищить, заповнює зірку сильного удару.",
  'Esquivar': "Ухилитися",
  'Abaixar e defender': "Пригнутися й блокувати",
  'Socar': "Бити",
  'Soco forte': "Сильний удар",
  'Aperte os socos para levantar!': "Тисни удари, щоб підвестися!",
  'Lutas vencidas: {n}': "Виграні бої: {n}",
  'Nocaute!': "Нокаут!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Зоряний шлях",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Кролики в космічних кораблях над поверхнею планети і в космосі: стріляй, затисни постріл, щоб захопити ціль, крутись, щоб відбивати постріли, і вибери шлях на розвилці. Компанія летить тим самим маршрутом, а наприкінці чекає бос.",
  'Pirueta': "Оберт",
  'Segure para travar a mira': "Затисни для захоплення",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Морквяний спецзагін",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Біжи й стріляй разом із компанією: морквомет цілиться у вісім напрямків, граната розчищає шлях, а хто звільнить зайченят із кліток, отримує підсилення. Наприкінці чекає дракон: від 1 до 4 людей.",
  'Andar e mirar': "Іти й цілитися",
  'Granada': "Граната",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Городній пінбол",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Стіл для пінболу на городі: тримай пружину, відскакуй від капусти й збий три морквини, щоб засвітилася нора кролика — вона випустить ще одну кульку. Три кульки, а надто сильне трясіння блокує стіл.",
  'Palhetas': "Фліпери",
  'Mola': "Пружина",
  'Sacudir': "Струснути",
  'Bola salva!': "Кульку врятовано!",
