  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Льотні випробування: дельтаплан, реактивний ранець і парашут. Пролети крізь кільця й приземлися на мішень, ближче до центру та м’яко.',
