  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Коротка покрокова RPG: кожен керує одним героєм загону. Обирайте разом, поєднуйте атаки й переможіть дракона із замку.",
