  "{nome}: {tiros} tiros, {pct}% de acerto": "{nome}: {tiros} пострілів, {pct}% влучань",
  "1 contra 3": "1 проти 3",
  "2 contra 2": "2 проти 2",
  "A armadilha de {nome} disparou: quem sai junto?": "Пастка {nome} спрацювала: хто виходить разом?",
  "A largada precisa de uma reta.": "Для старту потрібна пряма.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "Диво {nome} простояло 2 хвилини.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Та сама позиція втретє — нічия; 20 ходів лише дамками без взяття — теж.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Уночі дивись, на кого напали перевертні. Одне зілля рятує цю людину, а інше виводить когось із гри; кожне діє один раз.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Гра розсинхронізувалася між комп’ютерами й завершилася.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Шашка, що закінчує хід на останньому ряду, стає дамкою й ходить усією діагоналлю.",
  "A pista ainda não fecha a volta.": "Траса ще не замикає коло.",
