  "A turma está decidindo.": "Компанія вирішує.",
  "A turma inteira leva bem menos dano nesta rodada.": "Уся компанія отримує набагато менше шкоди в цьому раунді.",
  "A turma recupera vida no fim de três rodadas.": "Компанія відновлює здоров’я наприкінці трьох наступних раундів.",
