  "As pedras andam uma casa na diagonal, para a frente. Comer é obrigatório, também para trás, e vale o lance que come mais.": "Шашки ходять на одну клітинку по діагоналі вперед. Бити обов’язково, і назад теж, і зараховується хід, що б’є найбільше.",
  "As regras do xadrez inteiras. Clique na peça e depois na casa: as casas que valem acendem.": "Повні правила шахів. Клацни фігуру, а потім клітинку: дозволені клітинки світяться.",
