  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Козир — наступне значення після відкритої карти, він б'є всі інші. Між козирями: бубни, піки, чирви й трефи — зап.",
