  "Acertos em sequência: {n}": "Розв'язано поспіль: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Ходи за кидком кубика й купуй столицю, де зупинишся. Хто стає на чуже місто, платить оренду.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "У кожному рядку, стовпці й блоці 3 × 3 стоять числа від 1 до 9 без повторів.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Кожен отримує 3 карти. Руку забирає той, хто виграє 2 раунди з 3.",
  "Campeonato": "Чемпіонат",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "При 11 очках пара дивиться карти й вирішує, чи грати руку одинадцяти. Перемагає той, хто набере 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Зібравши весь регіон, будуй до 4 будівель: кожна підвищує оренду.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Сильний удар (★) витрачає одразу всі зірки й б'є болючіше.",
  "Dica": "Підказка",
  "Dica: este problema não pontua": "Підказка: ця задача не дає очок",
  "Dica: tira 10 segundos": "Підказка: мінус 10 секунд",
  "Eliminação": "На виліт",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Приклади кістку до кінця ланцюжка з тим самим числом.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Обери клітинку, потім число. Позначки олівцем бачиш тільки ти.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Ухилися від удару й одразу бий: це контратака, і вона дає зірку.",
  "Fora da corrida na volta {n}.": "Поза перегонами на колі {n}.",
  "Força das cartas": "Сила карт",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Перемагає найбільший статок наприкінці раундів або той, хто залишиться останнім.",
  "Iniciante": "Новачок",
  "Mestre": "Майстер",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "У серії кожна розв'язана задача веде до складнішої, а перша помилка все завершує.",
  "O número pequeno no botão diz quantos ainda faltam.": "Маленьке число на кнопці показує, скільки ще залишилося.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Усі п'ять трас поспіль проти комп'ютера, на очки.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Оголоси труко, і рука коштує 3. Той, хто відповідає, приймає, тікає або підвищує до 6, 9 чи 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Хто викладе всі кістки, забирає очки з рук інших. Коли «риба», забирає той, у кого на руці менше очок.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Немає потрібної кістки — бери з базару. Базар порожній — хід переходить далі.",
  "Sequência": "Серія",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Бий, коли рукавичка блищить: удар суперника перерветься, а ти отримаєш зірку.",
  "Treino livre": "Вільне тренування",
