  "Chuva de estrelas": "Зорепад",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Із захопленням: якщо затиснути два камені суперника між двома своїми, обидва знімаються; п'ять захоплень теж дають перемогу.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "З обмеженням 3-3 чорні не можуть зробити дві відкриті трійки одразу.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "З особливими виходами вихід дублем або кісточкою, що підходить до обох кінців, коштує подвійно; дубль на обидва кінці — вчетверо.",
