  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "У мінейро немає відкритої карти: козирі — 4 треф, 7 чирв, туз пік і 7 бубон.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "У мінейро рука коштує 2, а труко, шість, дев'ять і дванадцять — 4, 8, 10 і 12. При 10 очках — рука десяти: грати на 4 чи втекти й віддати 2.",
