  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Загадується таємна тварина, і кожен називає інших. Кожна спроба показує, що збігається з таємною: клас, харчування, де вона живе і вага. Хто вгадає за меншу кількість спроб, отримує більше очок.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Загадується таємний динозавр, і кожен називає інших. Кожна спроба показує, що збігається з таємним: період, харчування, група, довжина і де його знайшли. Хто вгадає за меншу кількість спроб, отримує більше очок.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Загадується таємний хімічний елемент, і кожен називає інші. Кожна спроба показує, що збігається з таємним: родина, агрегатний стан, період, група й атомний номер. Хто вгадає за меншу кількість спроб, отримує більше очок.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Загадується таємний штат Бразилії, і кожен називає інші. Кожна спроба показує відстань і напрямок до таємного, регіон, населення, площу, вихід до моря й кордон з іншою країною. Хто вгадає за меншу кількість спроб, отримує більше очок.",
